pub(crate) fn push_post_where(
    qb: &mut sqlx::QueryBuilder<'_, sqlx::Sqlite>,
    w: &crate::schema::PostWhereInput,
) -> bool {
    let mut any = false;
    if let Some(f) = &w.id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_sqlite::filters::push_string_filter(qb, "id", f);
    }
    if let Some(f) = &w.title {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_sqlite::filters::push_string_filter(qb, "title", f);
    }
    if let Some(f) = &w.body {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_sqlite::filters::push_string_nullable_filter(qb, "body", f);
    }
    if let Some(f) = &w.author_id {
        if any {
            qb.push(" AND ");
        }
        any = true;
        crate::engine::sqlx_sqlite::filters::push_string_filter(qb, "authorId", f);
    }
    if let Some(rel) = &w.author {
        if let Some(sub) = &rel.is {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push(
                "EXISTS (SELECT 1 FROM \"User\" t WHERE t.\"id\" = \"Post\".\"authorId\" AND (",
            );
            if !crate::engine::sqlx_sqlite::schema::push_user_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
        if let Some(sub) = &rel.is_not {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push(
                "NOT EXISTS (SELECT 1 FROM \"User\" t WHERE t.\"id\" = \"Post\".\"authorId\" AND (",
            );
            if !crate::engine::sqlx_sqlite::schema::push_user_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push("))");
        }
    }
    if let Some(group) = &w.and {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("(");
            if !push_post_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    if let Some(group) = &w.or {
        if any {
            qb.push(" AND ");
        }
        any = true;
        qb.push("(");
        let mut first = true;
        for sub in group {
            if !first {
                qb.push(" OR ");
            }
            first = false;
            qb.push("(");
            if !push_post_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
        qb.push(")");
    }
    if let Some(group) = &w.not {
        for sub in group {
            if any {
                qb.push(" AND ");
            }
            any = true;
            qb.push("NOT (");
            if !push_post_where(qb, sub) {
                qb.push("TRUE");
            }
            qb.push(")");
        }
    }
    any
}

